async function uploadVideoToPostBridge(videoUrl) {
  if (!POST_BRIDGE_API_KEY) {
    throw new Error("POST_BRIDGE_API_KEY is not configured");
  }
  let videoBuffer;
  if (videoUrl.startsWith("data:video/")) {
    const base64Data = videoUrl.split(",")[1];
    videoBuffer = Buffer.from(base64Data, "base64");
  } else {
    const videoResponse = await fetch(videoUrl);
    if (!videoResponse.ok) {
      throw new Error(`Failed to download video from ${videoUrl}`);
    }
    videoBuffer = Buffer.from(await videoResponse.arrayBuffer());
  }
  const videoSizeBytes = videoBuffer.length;
  const mimeType = "video/mp4";
  const fileName = `video-${Date.now()}.mp4`;
  const uploadUrlResponse = await fetch(`${POST_BRIDGE_API_URL}/v1/media/create-upload-url`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${POST_BRIDGE_API_KEY}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      name: fileName,
      mime_type: mimeType,
      size_bytes: videoSizeBytes
    })
  });
  if (!uploadUrlResponse.ok) {
    const error2 = await uploadUrlResponse.text();
    throw new Error(`Failed to create upload URL: ${error2}`);
  }
  const uploadData = await uploadUrlResponse.json();
  const uploadResponse = await fetch(uploadData.upload_url, {
    method: "PUT",
    headers: {
      "Content-Type": mimeType
    },
    body: videoBuffer
  });
  if (!uploadResponse.ok) {
    const error2 = await uploadResponse.text();
    throw new Error(`Failed to upload video: ${error2}`);
  }
  return uploadData.media_id;
}
