init_s3();
function segmentScriptForVeo(script, primaryDuration, availableDurations, totalWords) {
  const WORDS_PER_SECOND = 1.7;
  const maxWordsPerClip = Math.floor(primaryDuration * WORDS_PER_SECOND);
  const sentences = script.content.split(/(?<=[.!?])\s+/).filter((s6) => s6.length > 0);
  const words = script.content.split(/\s+/).filter((w5) => w5.length > 0);
  const segments = [];
  let currentStart = 0;
  let clipNumber = 1;
  let timeOffset = 0;
  while (currentStart < words.length) {
    const remainingWords = words.length - currentStart;
    let clipDuration = primaryDuration;
    let clipMaxWords = maxWordsPerClip;
    if (remainingWords <= maxWordsPerClip) {
      for (const d5 of [...availableDurations].sort((a5, b5) => a5 - b5)) {
        const maxForDuration = Math.floor(d5 * WORDS_PER_SECOND);
        if (remainingWords <= maxForDuration) {
          clipDuration = d5;
          clipMaxWords = maxForDuration;
          break;
        }
      }
    }
    const endIndex = Math.min(currentStart + clipMaxWords, words.length);
    let actualEnd = endIndex;
    if (endIndex < words.length) {
      let bestBreak = -1;
      for (let i6 = endIndex - 1; i6 >= currentStart + Math.floor(clipMaxWords * 0.4); i6--) {
        if (words[i6].match(/[.!?]$/)) {
          bestBreak = i6 + 1;
          break;
        }
      }
      if (bestBreak > currentStart) {
        actualEnd = bestBreak;
      } else {
        for (let i6 = endIndex; i6 < Math.min(endIndex + 5, words.length); i6++) {
          if (words[i6].match(/[.!?]$/)) {
            actualEnd = i6 + 1;
            break;
          }
        }
      }
    }
    const segmentWords = words.slice(currentStart, actualEnd);
    const segmentText = segmentWords.join(" ");
    const isLastClip = actualEnd >= words.length;
    segments.push({
      clipNumber,
      scriptSegment: segmentText,
      duration: clipDuration,
      wordCount: segmentWords.length,
      startTime: timeOffset,
      endTime: timeOffset + clipDuration,
      isLastClip
    });
    timeOffset += clipDuration;
    currentStart = actualEnd;
    clipNumber++;
  }
  return segments;
}
