// server/routes-calculators.ts
var CITIES = cities_default;
var CITY_ALIASES = {
  kiev: "kyiv",
  bombay: "mumbai",
  calcutta: "kolkata",
  madras: "chennai",
  saigon: "ho chi minh city",
  peking: "beijing",
  canton: "guangzhou",
  rangoon: "yangon",
  leningrad: "saint petersburg",
  constantinople: "istanbul"
};
function fold2(s6) {
  return s6.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}
var SEARCH_KEYS = CITIES.map((city) => {
  const keys = [fold2(city.n)];
  if (city.a) keys.push(fold2(city.a));
  return keys;
});
function registerCalculatorRoutes(app2) {
  const cors = (_req, res, next) => {
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type");
    next();
  };
  app2.options("/api/calculators/cities", cors, (_req, res) => res.sendStatus(204));
  app2.get("/api/calculators/cities", cors, (req, res) => {
    const raw = req.query.q || "";
    let q5 = fold2(raw.trim());
    if (q5.length < 2) return res.json([]);
    if (CITY_ALIASES[q5]) q5 = CITY_ALIASES[q5];
    const results = [];
    for (let i6 = 0; i6 < CITIES.length && results.length < 8; i6++) {
      if (SEARCH_KEYS[i6].some((k5) => k5.startsWith(q5))) {
        const city = CITIES[i6];
        results.push({
          name: city.n,
          region: city.r,
          country: city.c,
          timezone: city.t,
          lat: city.y,
          lon: city.x
        });
      }
    }
    res.setHeader("Cache-Control", "public, max-age=86400");
    res.json(results);
  });
}

